def placeholder_scan(*args, **kwargs):
    if args:
        s = args[0]
    else:
        s = ""
    positions = []
    inside = False
    i = 0
    while i < len(s):
        if inside:
            if s[i] == "'":
                # Check for escaped quote (doubled single quote)
                if i + 1 < len(s) and s[i+1] == "'":
                    i += 2
                    continue
                else:
                    inside = False
                    i += 1
            else:
                i += 1
        else:
            if s[i] == "'":
                inside = True
                i += 1
            elif s[i] == "?":
                positions.append(i)
                i += 1
            else:
                i += 1
    return positions
